import React from 'react';
import { Link } from 'react-router-dom';

interface ButtonProps {
  children: React.ReactNode;
  to?: string;
  variant?: 'primary' | 'secondary' | 'outline' | 'text';
  className?: string;
  onClick?: () => void;
  type?: 'button' | 'submit' | 'reset';
}

const Button: React.FC<ButtonProps> = ({ 
  children, 
  to, 
  variant = 'primary', 
  className = '', 
  onClick,
  type = 'button'
}) => {
  const baseStyles = "inline-flex items-center justify-center px-6 py-3 border text-base font-medium rounded-sm focus:outline-none transition-all duration-200";

  const variants = {
    primary: "border-transparent text-white bg-accent hover:bg-blue-800 shadow-sm",
    secondary: "border-transparent text-accent bg-blue-50 hover:bg-blue-100",
    outline: "border-accent text-accent bg-transparent hover:bg-blue-50",
    text: "border-transparent text-accent hover:text-blue-800 px-0 underline-offset-4 hover:underline"
  };

  const combinedClasses = `${baseStyles} ${variants[variant]} ${className}`;

  if (to) {
    return (
      <Link to={to} className={combinedClasses}>
        {children}
      </Link>
    );
  }

  return (
    <button type={type} className={combinedClasses} onClick={onClick}>
      {children}
    </button>
  );
};

export default Button;

