// components/FloatingAssistant.tsx

import React, { useState, useEffect } from 'react';
import { X, Bot, WhatsApp } from 'lucide-react';

const FloatingAssistant = () => {
    const [isAssistantVisible, setIsAssistantVisible] = useState(false);
    const [isDismissed, setIsDismissed] = useState(sessionStorage.getItem('ai_assistant_dismissed') === 'true');
    const whatsAppNumber = '1234567890'; // Placeholder - Replace with user's number
    const aiLink = 'https://agent.jotform.com/019b3f0fa49d753791c4f0020584579e405a';

    useEffect(() => {
        if (!isDismissed) {
            const timeoutId = setTimeout(() => {
                setIsAssistantVisible(true);
            }, 5000); // 5 seconds delay

            return () => clearTimeout(timeoutId); // Cleanup on unmount or re-render
        }
    }, [isDismissed]);

    const handleDismiss = () => {
        setIsAssistantVisible(false);
        setIsDismissed(true);
        sessionStorage.setItem('ai_assistant_dismissed', 'true');
    };

    const handleOpenAI = () => {
        window.open(aiLink, '_blank');
    };

    if (isDismissed) {
        return null; // Don't render anything if dismissed
    }

    return (
        <div className="fixed bottom-6 right-6 z-50 flex flex-col items-end gap-2">
            {isAssistantVisible && (
                <div className="bg-white rounded-lg shadow-md p-4 w-64 text-sm flex flex-col gap-2">
